// Function to combine elements from multiple ranges into one array
int combine_elements_from_ranges(float arr[], int ranges[][2], int num_ranges, float combined[]);
int combine_elements_from_ranges(float arr[], int ranges[][2], int num_ranges, float combined[]) {
  int combined_size = 0;

  // Iterate over each range
  for (int i = 0; i < num_ranges; i++) {
      int start = ranges[i][0];
      int end = ranges[i][1];

      // Add the elements from the current range into the combined array
      for (int j = start; j <= end; j++) {
          combined[combined_size] = arr[j];
          combined_size++;
      }
  }

  return combined_size;  // Return the size of the combined array
}

// Function to calculate the sum of all elements in an array
float array_sum(float arr[], int size);
float array_sum(float arr[], int size) {
  float sum = 0.0;
  
  // Loop through the array and add each element to the sum
  for (int i = 0; i < size; i++) {
      sum += arr[i];
  }
  
  return sum;
}

// Function to find the most probable (mode) value using bucketization
float find_mode_with_buckets(float arr[], int size, float precision);
float find_mode_with_buckets(float arr[], int size, float precision) {
  int bucket_count = 0;

  const int bucket_size = (int)(1 / precision);
  float bucket_map[bucket_size];  // Array to store frequency of each bucket
  for (int i = 0; i < bucket_size; i++) {
      bucket_map[i] = 0;
  }

  for (int i = 0; i < size; i++) {
      // Round the value to the nearest bucket based on the precision
      int bucket_index = (int)(arr[i] / precision);
      bucket_map[bucket_index]++;
  }

  // Find the bucket with the maximum frequency
  int max_count = 0;
  float mode = 0;
  for (int i = 0; i < bucket_size; i++) {
      if (bucket_map[i] > max_count) {
          max_count = bucket_map[i];
          mode = (i * precision);  // Convert back to the original value range
      }
  }
  return mode;
}

